import React, { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import Header from "../components/header";
import Footer from "../components/footer";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "./DescriptionOnly.css";

const DescriptionOnly = () => {
  const [description, setDescription] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const category = location.state?.category || "";

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!description) {
      toast.error("Please write a description!");
      return;
    }

    setLoading(true);

    try {
      const response = await fetch("http://localhost:5000/api/search/text", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          query: description,
          category: category
        })
      });

      const data = await response.json();

      if (data.wrongCategory) {
        toast.error(data.message);
        setLoading(false);
        return;
      }

      if (data.success) {
        navigate("/results", { state: { products: data.products } });
      } else {
        toast.error("Search failed: " + data.message);
      }

    } catch (error) {
      toast.error("Error: " + error.message);
    }

    setLoading(false);
  };

  return (
    <>
      <ToastContainer position="top-right" autoClose={3000} />
      <Header />
      <div className="desc-container">
        <h2>Describe Product - {category}</h2>
        <form onSubmit={handleSubmit}>
          <label>Description</label>
          <textarea
            placeholder={`Example: ${category === "Electronics" ? "wireless earphones with mic" : category === "Makeup" ? "long lasting matte lipstick red color" : "modern wall clock for living room"}`}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            required
          ></textarea>
          <button type="submit" disabled={loading}>
            {loading ? "Searching..." : "Submit"}
          </button>
        </form>
      </div>
      <Footer />
    </>
  );
};

export default DescriptionOnly;
